// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _test(address user, uint256 amt, uint256 r, uint256 val) internal {
        val = bound(val, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0 && val > 0);
        vm.assume(address(this).balance >= val);
        vm.assume(user == address(this));
        try c.setRewardRate(r) {} catch { return; }
        try c.deposit{value: val}() {} catch { return; }
        uint256 snap;
        try c.rateSnapshot(user) returns (uint256 __r) { snap = __r; } catch { return; }
        assertTrue(snap == r);
    }

    function testFuzz_test(address user, uint256 amt, uint256 r, uint256 val) public {
        _test(user, amt, r, val);
    }

    receive() external payable {}
}
